window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cbb3445bd8733366"]={"versions": [{"id": "FIG-cbb3445bd8733366", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Protokoll- und Frame-Layout-Diagramm (Paketaufbau / Bit- und Byte-Mapping) aus der Spezifikation des AUTOSAR Intrusion Detection System Protocols (AUTOSAR PRS IntrusionDetectionSystem). Es visualisiert die Einbettung des optionalen bzw. alternativen Segments <code>Context Data</code> in die übergeordnete IDS-Nachrichtenstruktur sowie dessen internen Aufbau bei kurzer Längenangabe („Context Data Size Short“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die übergeordnete Nachricht setzt sich aus vier sequenziellen Blöcken zusammen:</p>\n<ul class=\"fig-list\"><li><code>Header</code>\n</li><li><code>Timestamp</code>\n</li><li><code>Context Data</code> (hervorgehoben als aktives/detailliertes Segment)\n</li><li><code>Signature</code>\n</li></ul>\n<p class=\"fig-p\">Der vergrößerte Detailaufbau von <code>Context Data</code> umfasst:</p>\n<ul class=\"fig-list\"><li><code>Context Data Length</code>: 1 Byte (Byte 0) mit Bit-Indizierung <code>7 msb</code> bis <code>lsb 0</code>.\n</li><li><code>Context Data</code>: Nutzdatenfeld variabler Länge, beginnend ab <code>Byte 1</code> über <code>Byte 2</code>, <code>Byte 3</code>, <code>Byte ..</code> bis <code>Byte n</code>.\n</li><li>Gesamte Rahmengröße unter der geschweiften Klammer: <code>Context Data frame size: 2 ... 127 Bytes</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Übertragung und Verarbeitung erfolgt linear in Byte-Reihenfolge (Big-Endian- bzw. Network-Byte-Order-Darstellung):</p>\n<ol class=\"fig-list\"><li>Der Frame startet mit dem <code>Header</code>, gefolgt von <code>Timestamp</code>.\n</li><li>Das Feld <code>Context Data</code> beginnt an Byte 0 mit <code>Context Data Length</code>, welches die Länge der nachfolgenden Nutzdaten kodiert (wobei das MSB Bit 7 bis LSB Bit 0 ein 1-Byte-Längenfeld aufspannen).\n</li><li>Direkt im Anschluss folgen die Nutzdatenbytes ab Byte 1 bis Byte n.\n</li><li>Nach Abschluss des Context-Data-Blocks folgt die kryptografische <code>Signature</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Serialisierung und Deserialisierung des IDS-Protokolls:</p>\n<ul class=\"fig-list\"><li>Die Variante „Context Data Size Short“ begrenzt die Frame-Größe des Context-Data-Blocks auf einen Wertebereich von minimal 2 bis maximal 127 Bytes (1 Byte Längenfeld + 1 bis 126 Bytes Nutzdaten).\n</li><li>Das Längenfeld belegt genau Byte 0 (8 Bit, msb 7 bis lsb 0).\n</li><li>Parser müssen vor der Auswertung der eigentlichen Kontextdaten das Längenfeld an Byte 0 auswerten, um die Segmentgrenze vor dem nachfolgenden Signatur-Block exakt zu bestimmen.\n</li></ul>"}, {"id": "FIG-ae4bf48ae5a7f108", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Protokoll- und Frame-Layout-Diagramm (Paketaufbau / Bit- und Byte-Mapping) aus der Spezifikation des AUTOSAR Intrusion Detection System Protocols (AUTOSAR PRS IntrusionDetectionSystem). Es visualisiert die Einbettung des Segments <code>Context Data Frame</code> in die übergeordnete IDS-Protokollstruktur sowie dessen internen Aufbau bei kurzer Längenangabe („Context Data Size Short“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die übergeordnete Nachricht setzt sich aus vier sequenziellen Rahmenblöcken zusammen:</p>\n<ul class=\"fig-list\"><li><code>Event Frame</code>\n</li><li><code>Timestamp</code>\n</li><li><code>Context Data Frame</code> (hervorgehoben als detailliertes Segment)\n</li><li><code>Signature Frame</code>\n</li></ul>\n<p class=\"fig-p\">Der vergrößerte Detailaufbau von <code>Context Data Frame</code> umfasst:</p>\n<ul class=\"fig-list\"><li><code>Context Data Length</code>: 1 Byte (Byte 0) mit Bit-Indizierung <code>7 msb</code> bis <code>lsb 0</code>.\n</li><li><code>Context Data</code>: Nutzdatenfeld variabler Länge von <code>Byte 1</code>, <code>Byte 2</code>, <code>Byte 3</code>, <code>Byte ..</code> bis <code>Byte n</code>.\n</li><li>Gesamtrahmen-Klammer: beschriftet mit <code>Context Data frame ...</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Übertragung und Verarbeitung erfolgt linear in Byte-Reihenfolge:</p>\n<ol class=\"fig-list\"><li>Die Nachricht beginnt mit dem <code>Event Frame</code>, gefolgt von <code>Timestamp</code>.\n</li><li>Das Segment <code>Context Data Frame</code> beginnt an Byte 0 mit <code>Context Data Length</code> (MSB Bit 7 bis LSB Bit 0).\n</li><li>Direkt daran schließen sich die Nutzdatenbytes von Byte 1 bis Byte n an.\n</li><li>Nach dem Context-Data-Segment folgt der <code>Signature Frame</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Serialisierung und Deserialisierung des IDS-Protokolls:</p>\n<ul class=\"fig-list\"><li>Die Variante „Context Data Size Short“ begrenzt die Frame-Größe des Context-Data-Blocks auf einen Wertebereich von minimal 2 bis maximal 127 Bytes (1 Byte Längenfeld + 1 bis 126 Bytes Nutzdaten).\n</li><li>Das Längenfeld belegt genau Byte 0 (8 Bit, msb 7 bis lsb 0).\n</li><li>Parser müssen vor der Auswertung der eigentlichen Kontextdaten das Längenfeld an Byte 0 auswerten, um die Segmentgrenze vor dem nachfolgenden Signatur-Block exakt zu bestimmen.\n</li></ul>"}], "trans": [{"from": "FIG-cbb3445bd8733366", "to": "FIG-ae4bf48ae5a7f108", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Übergeordnete Protokollrahmen-Struktur: Das erste Element <code>Header</code> wurde umbenannt in <code>Event Frame</code>.\n</li><li>Übergeordnete Protokollrahmen-Struktur: Das dritte Element <code>Context Data</code> wurde umbenannt in <code>Context Data Frame</code>.\n</li><li>Übergeordnete Protokollrahmen-Struktur: Das vierte Element <code>Signature</code> wurde umbenannt in <code>Signature Frame</code>.\n</li><li>Untere Gesamtlängenbeschriftung: Der Text unter der geschweiften Klammer wurde von <code>Context Data frame size: 2 ... 127 Bytes</code> zu <code>Context Data frame ...</code> (abgeschnitten) geändert.\n</li></ul>"}]};
